    async def get_first_list_item(
        self,
        where: Callable[[NoteFields], zbt.Expr],
        *,
        sort: str | Sequence[str] | None = None,
        expand: Sequence[str] | None = None,
        fields: str | None = None,
        search: str | None = None,
    ) -> Note:
        return await self._c.get_first_list_item(
            where(NoteFields()).compile(), sort=sort, expand=expand, fields=fields, search=search
        )

    async def get_page(
        self,
        *,
        where: Callable[[NoteFields], zbt.Expr] | None = None,
        sort: str | Sequence[str] | None = None,
        expand: Sequence[str] | None = None,
        cursor: str | None = None,
        limit: int = 30,
        with_total: bool = False,
        fields: str | None = None,
        search: str | None = None,
    ) -> zbt.TypedCursorPage[Note]:
        return await self._c.get_page(
            cursor=cursor,
            limit=limit,
            filter=where(NoteFields()).compile() if where else None,
            sort=sort,
            expand=expand,
            with_total=with_total,
            fields=fields,
            search=search,
        )

    def iterate(
        self,
        *,
        where: Callable[[NoteFields], zbt.Expr] | None = None,
        sort: str | Sequence[str] | None = None,
        expand: Sequence[str] | None = None,
        batch: int = 100,
        fields: str | None = None,
        search: str | None = None,
    ) -> AsyncIterator[Note]:
        return self._c.iterate(
            batch=batch,
            filter=where(NoteFields()).compile() if where else None,
            sort=sort,
            expand=expand,
            fields=fields,
            search=search,
        )

    async def get_full_list(
        self,
        *,
        where: Callable[[NoteFields], zbt.Expr] | None = None,
        sort: str | Sequence[str] | None = None,
        expand: Sequence[str] | None = None,
        batch: int = 100,
        fields: str | None = None,
        search: str | None = None,
    ) -> list[Note]:
        return await self._c.get_full_list(
            batch=batch,
            filter=where(NoteFields()).compile() if where else None,
            sort=sort,
            expand=expand,
            fields=fields,
            search=search,
        )

    async def create(
        self, data: NoteCreate, *, expand: Sequence[str] | None = None, fields: str | None = None
    ) -> Note:
        return await self._c.create(data.to_map(), expand=expand, fields=fields)

    async def update(
        self,
        record_id: str,
        data: NoteUpdate,
        *,
        expand: Sequence[str] | None = None,
        fields: str | None = None,
    ) -> Note:
        return await self._c.update(record_id, data.to_map(), expand=expand, fields=fields)

    async def delete(self, record_id: str) -> None:
        await self._c.delete(record_id)

    def filter(self, fn: Callable[[NoteFields], zbt.Expr]) -> str:
        """Compile a typed filter expression to a server filter string."""
        return fn(NoteFields()).compile()

    def file_url(
        self,
        record: Note | Mapping[str, Any],
        *,
        field: NoteFileField,
        download: bool = False,
        thumb: str | None = None,
        token: str | None = None,
    ) -> str:
        record_id = record["id"] if isinstance(record, Mapping) else record.id
        filename = {
            NoteFileField.ATTACHMENT: record.get("attachment")
            if isinstance(record, Mapping)
            else record.attachment,
        }[field]
        return self._c.file_url(
            {"id": record_id, "collectionName": "notes"},
            filename,
            download=download,
            thumb=thumb,
            token=token,
        )


