# ---- Client ----


class ZbClient:
    def __init__(self, raw: ZigBase, *, owned: bool = False) -> None:
        self.raw = raw
        self.owned = owned
        self.profiles = ProfilesService(raw)
        self.tags = TagsService(raw)
        self.photos = PhotosService(raw)
        self.privatePhotos = PrivatePhotosService(raw)
        self.messages = MessagesService(raw)
        self.winks = WinksService(raw)
        self.subscriptions = SubscriptionsService(raw)
        self.notes = NotesService(raw)

    @property
    def auth_store(self) -> AuthStore:
        return self.raw.auth_store

    def send(
        self,
        method: str,
        path: str,
        *,
        query: dict[str, str] | None = None,
        body: Mapping[str, Any] | None = None,
        headers: dict[str, str] | None = None,
    ) -> Any:
        return self.raw.send(method, path, query=query, body=body, headers=headers)

    def close(self) -> None:
        if self.owned:
            self.raw.close()


def create_client(url: str, **kwargs: Any) -> ZbClient:
    kwargs.setdefault("auth_collection", "profiles")
    return ZbClient(ZigBase(url, **kwargs), owned=True)


class AsyncZbClient:
    def __init__(self, raw: AsyncZigBase, *, owned: bool = False) -> None:
        self.raw = raw
        self.owned = owned
        self.profiles = AsyncProfilesService(raw)
        self.tags = AsyncTagsService(raw)
        self.photos = AsyncPhotosService(raw)
        self.privatePhotos = AsyncPrivatePhotosService(raw)
        self.messages = AsyncMessagesService(raw)
        self.winks = AsyncWinksService(raw)
        self.subscriptions = AsyncSubscriptionsService(raw)
        self.notes = AsyncNotesService(raw)
        self.profilesRealtime = ProfilesRealtime(raw)
        self.tagsRealtime = TagsRealtime(raw)
        self.photosRealtime = PhotosRealtime(raw)
        self.privatePhotosRealtime = PrivatePhotosRealtime(raw)
        self.messagesRealtime = MessagesRealtime(raw)
        self.winksRealtime = WinksRealtime(raw)
        self.subscriptionsRealtime = SubscriptionsRealtime(raw)
        self.notesRealtime = NotesRealtime(raw)

    @property
    def auth_store(self) -> AuthStore:
        return self.raw.auth_store

    async def send(
        self,
        method: str,
        path: str,
        *,
        query: dict[str, str] | None = None,
        body: Mapping[str, Any] | None = None,
        headers: dict[str, str] | None = None,
    ) -> Any:
        return await self.raw.send(method, path, query=query, body=body, headers=headers)

    async def aclose(self) -> None:
        if self.owned:
            await self.raw.aclose()


def create_async_client(url: str, **kwargs: Any) -> AsyncZbClient:
    kwargs.setdefault("auth_collection", "profiles")
    return AsyncZbClient(AsyncZigBase(url, **kwargs), owned=True)
